  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('segments must be a non-empty list')
    names = []
    importances = []
    minima = []
    capacities = []
    for i, seg in enumerate(segments):
        if not isinstance(seg, dict):
            raise ValueError(f'segment {i} must be a dict')
        name = seg.get('name')
        if name is None:
            raise ValueError(f'segment {i} missing name')
        importance = seg.get('importance')
        min_val = seg.get('minimum')
        cap = seg.get('capacity')
        if not all(isinstance(x, int) for x in (importance, min_val, cap)):
            raise ValueError('importance, minimum, capacity must be integers')
        if min_val < 0 or cap < 0:
            raise ValueError('minimum and capacity must be non-negative')
        if min_val > cap:
            raise ValueError('minimum exceeds capacity')
        names.append(name)
        importances.append(importance)
        minima.append(min_val)
        capacities.append(cap)
    total_min = sum(minima)
    total_cap = sum(capacities)
    if budget < total_min:
        raise ValueError('budget below total minimum quota')
    if budget > total_cap:
        raise ValueError('budget exceeds total capacity')
    allocs = list(minima)
    remaining = budget - total_min
    n = len(segments)
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i in range(n):
            if allocs[i] >= capacities[i]:
                continue
            score = importances[i] / (allocs[i] + 1)
            if score > best_score:
                best_score = score
                best_idx = i
        if best_idx == -1:
            break
        allocs[best_idx] += 1
        remaining -= 1
    total = sum(allocs)
    by_name = {names[i]: allocs[i] for i in range(n)}
    return {
        'allocations': allocs,
        'by_name': by_name,
        'total': total
    }"
}
